// Generated from the per-market intertie research described in docs/intertie-trends.md.
// Emissions are generation CO2 intensity in kg CO2e/MWh. Prices are annual average wholesale
// (or bulk-supply proxy) $/MWh: nominal U.S. dollars through 2024, real 2024 dollars after.
// Corridor years are when the real path first entered service (existing routes) or could first
// have been ordered (new routes), and when trading stopped if it was cut off for good.

export type YearSeries = readonly (readonly [year: number, value: number])[];

export interface IntertieMarketTrendType {
  emissions: YearSeries;
  prices: YearSeries;
  /** Which grid the numbers describe; price bases and every source are in the docs */
  emissionsBasis: string;
  emissionsSource: string;
}

